mapLayout = emu:read32(0x202e828) -- gMapHeader
secondaryTileset = emu:read32(mapLayout + 0x14)
metatileAttributes = emu:read32(secondaryTileset + 0x10)

idx = 0x200
while idx < 0x363 do
    attrs = emu:read16(metatileAttributes+(idx-0x200)*2)
    behaviorId = attrs & 0xff
    layerId = attrs >> 12
    console:log(string.format(
        "%.3X => %.2X [%s], layer %.1X, possible spawn: [MOVE2 %s]", 
        idx, behaviorId, attrMap[behaviorId], layerId, moveMap[idx-0x200]
    ))
    idx = idx + 1
end